/**
 * What the import stage says was understood, as short lines: where the
 * start came from, the other ways in, the doors, what a SketchUp file held,
 * what was left out, and how many warnings wait in the report.
 */

export interface ImportSummaryInput {
  title: string;
  entrySource: { kind: string; scene?: string; camera?: string };
  warnings: readonly string[];
  skp?: {
    scenes?: number;
    instances?: number;
    materials: number;
    textures: number;
    start: string | null;
    arrivals: readonly string[];
    doors: ReadonlyArray<{ label: string; name?: string; href?: string }>;
    leftOut: readonly string[];
  };
  files: ReadonlyArray<{ path: string; bytes: Uint8Array }>;
}

const plural = (n: number, one: string, many = `${one}s`): string => `${n} ${n === 1 ? one : many}`;

const sizeOf = (bytes: number): string => (bytes < 1024 * 1024 ? `${Math.max(1, Math.round(bytes / 1024))} kB` : `${(bytes / (1024 * 1024)).toFixed(1)} MB`);

function startLine(source: ImportSummaryInput['entrySource']): string {
  switch (source.kind) {
    case 'skp-scene':
      return `Start: the scene “${source.scene ?? ''}”.`;
    case 'entry-flag':
      return 'Start: the entry point you gave.';
    case 'spawn-camera':
      return `Start: the entry camera${source.camera ? ` “${source.camera}”` : ''}.`;
    case 'active-camera':
      return `Start: the scene’s camera${source.camera ? ` “${source.camera}”` : ''}.`;
    default:
      return 'Start: in front of the model, framed to fit.';
  }
}

export function summarizeImport(built: ImportSummaryInput): string[] {
  const lines: string[] = [startLine(built.entrySource)];
  const skp = built.skp;
  if (skp) {
    if (skp.arrivals.length > 0) lines.push(`Also reached by name: ${skp.arrivals.join(', ')}.`);
    if (skp.doors.length > 0) lines.push(`${plural(skp.doors.length, 'door')}: ${skp.doors.map((d) => d.label).join(', ')}.`);
    lines.push(`${plural(skp.textures, 'texture')}, ${plural(skp.materials, 'material')}.`);
    if (skp.leftOut.length > 0) lines.push(`Left out (hidden): ${skp.leftOut.join(', ')}.`);
  }
  const total = built.files.reduce((n, f) => n + f.bytes.length, 0);
  lines.push(`World folder: ${plural(built.files.length, 'file')}, ${sizeOf(total)}.`);
  if (built.warnings.length > 0) {
    lines.push(`${plural(built.warnings.length, 'warning')} in the report${built.warnings.length > 3 ? ', the first three:' : ':'}`);
    for (const w of built.warnings.slice(0, 3)) lines.push(w);
  }
  return lines;
}
