/**
 * Saving a world folder to the visitor's computer: into a folder they pick,
 * where the browser has a folder picker, and as one zip download where it
 * has none. Nothing here knows how the world was made.
 */
import { zipStore } from './zipStore';

/** The directory picker, where the browser has one; the type is not in the DOM library yet. */
interface DirectoryHandle {
  getDirectoryHandle(name: string, opts?: { create?: boolean }): Promise<DirectoryHandle>;
  getFileHandle(name: string, opts?: { create?: boolean }): Promise<{ createWritable(): Promise<{ write(data: BufferSource): Promise<void>; close(): Promise<void> }> }>;
}
type PickerWindow = Window & { showDirectoryPicker?: (opts?: { mode?: 'readwrite' }) => Promise<DirectoryHandle> };

export interface WorldFolder {
  title: string;
  files: ReadonlyArray<{ path: string; bytes: Uint8Array }>;
}

/** True where the browser lets a page write into a folder the visitor picks. */
export function canPickFolder(doc: Document): boolean {
  return Boolean((doc.defaultView as PickerWindow | null)?.showDirectoryPicker);
}

/**
 * Saves `world` and says how: `folder` when it was written into a folder the
 * visitor picked, `zip` when it was downloaded as one file. Rejects with an
 * `AbortError` when the visitor closed the picker.
 */
export async function saveFolder(doc: Document, world: WorldFolder): Promise<'folder' | 'zip'> {
  const win = doc.defaultView as PickerWindow | null;
  if (win?.showDirectoryPicker) {
    const root = await win.showDirectoryPicker({ mode: 'readwrite' });
    for (const f of world.files) {
      const parts = f.path.split('/');
      let dir = root;
      for (const part of parts.slice(0, -1)) dir = await dir.getDirectoryHandle(part, { create: true });
      const handle = await dir.getFileHandle(parts[parts.length - 1]!, { create: true });
      const w = await handle.createWritable();
      await w.write(f.bytes as BufferSource);
      await w.close();
    }
    return 'folder';
  }
  const zip = zipStore(world.files);
  const url = URL.createObjectURL(new Blob([zip as BlobPart], { type: 'application/zip' }));
  const a = doc.createElement('a');
  a.href = url;
  a.download = `${world.title || 'world'}.zip`;
  doc.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
  return 'zip';
}
