    if (/^[a-z][a-z0-9+.-]*:/i.test(uri) || uri.startsWith('//'))
        return false;
    // Absolute on any platform: a leading separator, or a drive letter.
    if (/^[\\/]/.test(uri) || /^[a-z]:[\\/]/i.test(uri))
        return false;
