/**
 * The room a world made in the tab is.
 *
 * A world is shared when its document names where its visitors meet and
 * which room they meet in. Where rooms meet is the shell's deployment's to
 * say, beside its sign-in in webverse.config.json (`rooms.address`), never
 * the page's or the model's. The room's name is made here, once per
 * conversion, and is written into the document: publishing the same world
 * again keeps its room, and two worlds with the same title never share one.
 *
 * A deployment that names no meeting place makes worlds with no room, and
 * each visitor is alone in them.
 */

type Fetch = (url: string, init?: RequestInit) => Promise<Response>;
/** Fills the bytes it is handed with random values, in place. */
type FillRandom = (bytes: Uint8Array<ArrayBuffer>) => void;

/** What the converter is told: where the room meets, and its name. */
export interface WorldRoom {
  sync: string;
  session: string;
}

const LOOPBACK = new Set(['localhost', '127.0.0.1', '[::1]']);

/** The deployment's `{ "rooms": { "address": "wss://meet.example/" } }`; null without a usable one (a secure socket, or in clear on this machine). */
export function readShellRooms(json: unknown): string | null {
  const rooms = json && typeof json === 'object' ? (json as { rooms?: unknown }).rooms : undefined;
  const address = rooms && typeof rooms === 'object' ? (rooms as { address?: unknown }).address : undefined;
  if (typeof address !== 'string') return null;
  let url: URL;
  try {
    url = new URL(address);
  } catch {
    return null;
  }
  if (url.protocol !== 'wss:' && !(url.protocol === 'ws:' && LOOPBACK.has(url.hostname))) return null;
  return url.href;
}

/** A room name nobody else has: `room-` and sixteen hex digits. */
export function newRoomName(fill: FillRandom = (bytes) => void globalThis.crypto.getRandomValues(bytes)): string {
  const bytes = new Uint8Array(new ArrayBuffer(8));
  fill(bytes);
  return `room-${Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('')}`;
}

/**
 * The room for a world about to be made, from the config beside the shell's
 * own files; empty when the deployment names no meeting place or cannot be
 * asked, so the conversion goes on either way.
 */
export async function roomForNewWorld(shellBase: string, fetchImpl: Fetch, fill?: FillRandom): Promise<WorldRoom | Record<string, never>> {
  let sync: string | null = null;
  try {
    const res = await fetchImpl(new URL('webverse.config.json', shellBase).href);
    sync = res.ok ? readShellRooms(await res.json()) : null;
  } catch {
    sync = null;
  }
  return sync ? { sync, session: newRoomName(fill) } : {};
}
