/**
 * Publishing the world in the tab: the import card's other way out, beside
 * saving the folder.
 *
 * Where it publishes is the shell's deployment's, declared beside its
 * sign-in in webverse.config.json (`publish.endpoint`), never a world's or
 * the page's: a page that boots the shell may be a world author's. Without
 * both the host and a sign-in, the card offers only the folder.
 *
 * The credential is the visitor's own sign-in with the shell's issuer, as
 * the shell's client: the publish host authorises by ownership and takes the
 * pass of the clients it names, and no world sits between the tab and the
 * host, so nothing can replay it. The sign-in is made in a popup with the
 * planet's primitives (`planet/signIn.ts`) and kept in this tab's session
 * only; the return page hands the code back on the shell's own origin.
 *
 * The files go up the publish protocol the command line speaks
 * (`publishFiles`), so a world published from here is the same world.
 */
import { publishFiles, PublishError, type PublishFilesResult } from '@fivesqd/ingest/browser';
import { trustedOrigin } from '../scene/planet/planetEdit';
import {
  discoverIssuer,
  finishSignIn,
  PENDING_SIGN_IN,
  readShellSignIn,
  startSignIn,
  upstreamToken,
  type IssuerEndpoints,
  type KeyStore,
  type ShellSignIn,
  type SignInReturn,
} from '../scene/planet/signIn';

type Fetch = (url: string, init?: RequestInit) => Promise<Response>;

/** Where this shell publishes, and the host's name for the button. */
export interface PublishTarget {
  endpoint: string;
  host: string;
}

/** The deployment's `{ "publish": { "endpoint": "https://worlds.example" } }`; null without a usable one (https, or in clear on this machine). */
export function readShellPublish(json: unknown): PublishTarget | null {
  const p = ((json && typeof json === 'object' ? (json as { publish?: unknown }).publish : undefined) ?? null) as Record<string, unknown> | null;
  if (!p || typeof p !== 'object' || typeof p.endpoint !== 'string') return null;
  const origin = trustedOrigin(p.endpoint);
  if (!origin) return null;
  const endpoint = p.endpoint.replace(/\/+$/, '');
  return { endpoint, host: new URL(endpoint).host };
}

export interface TabPublisherOptions {
  /** Where the shell's own files are: the config and the return page sit beside them. */
  shellBase: string;
  fetchImpl: Fetch;
  /** This tab's session: where the sign-in in progress and the sign-in itself are kept. */
  pending?: KeyStore;
  /** Opens the sign-in popup; null when the browser refused. */
  openWindow?: (url: string) => Window | null;
  /** The deployment's config as parsed JSON; by default fetched from beside the shell's files. */
  config?: () => Promise<unknown>;
  /** Calls `fn` every `ms` until the returned stop is called; by default the page's timer. Watches for the sign-in window being closed. */
  every?: (fn: () => void, ms: number) => () => void;
}

export interface TabPublisher {
  /** Where this shell publishes, or null when its deployment names no host or no sign-in. */
  target(): Promise<PublishTarget | null>;
  /** Whether this tab already holds a sign-in a publish can use. */
  signedIn(): Promise<boolean>;
  /** Publishes the files as a world (a new one, or `worldId` again); signs the visitor in first when the tab holds no sign-in. */
  publish(files: ReadonlyArray<{ path: string; bytes: Uint8Array }>, worldId?: string): Promise<PublishFilesResult>;
  /** What the return page handed back (the page's `message` event): finishes the sign-in that waits for it. */
  returned(origin: string, data: unknown): void;
}

interface Found {
  signIn: ShellSignIn;
  target: PublishTarget;
}

export function createTabPublisher(o: TabPublisherOptions): TabPublisher {
  const returnPage = new URL('signin-done.html', o.shellBase).href;
  const session = (): KeyStore | undefined => o.pending ?? globalThis.sessionStorage;

  let found: Promise<Found | null> | undefined;
  const find = (): Promise<Found | null> => {
    found ??= (async () => {
      let json: unknown = null;
      try {
        if (o.config) json = await o.config();
        else {
          const res = await o.fetchImpl(new URL('webverse.config.json', o.shellBase).href);
          json = res.ok ? await res.json() : null;
        }
      } catch {
        json = null;
      }
      const signIn = readShellSignIn(json);
      const target = readShellPublish(json);
      return signIn && target ? { signIn, target } : null;
    })();
    return found;
  };

  const held = (f: Found): string | null => {
    const s = session();
    return s ? upstreamToken(s, f.signIn.issuer, f.signIn.clientId) : null;
  };

  // One sign-in waits at a time; the return page's message settles it.
  let waiting: { origin: string; settle: (m: SignInReturn) => void } | null = null;

  const every =
    o.every ??
    ((fn: () => void, ms: number) => {
      const timer = setInterval(fn, ms);
      return () => clearInterval(timer);
    });

  const signIn = async (f: Found): Promise<string> => {
    const s = session();
    if (!s) throw new PublishError('This browser keeps no session for the tab, so it cannot sign you in here.');
    let endpoints: IssuerEndpoints | null;
    try {
      endpoints = await discoverIssuer(f.signIn.issuer, o.fetchImpl);
    } catch {
      endpoints = null;
    }
    if (!endpoints) throw new PublishError('The sign-in could not be reached; try again later.');
    const url = await startSignIn({ issuer: f.signIn.issuer, clientId: f.signIn.clientId, redirectUri: returnPage, endpoints, pending: s });
    const mine = { origin: new URL(returnPage).origin, settle: (_: SignInReturn): void => undefined };
    let closed = (_: PublishError): void => undefined;
    const message = new Promise<SignInReturn>((settle, refuse) => {
      mine.settle = settle;
      closed = refuse;
    });
    waiting = mine;
    const opened = o.openWindow ? o.openWindow(url) : (globalThis.open?.(url, 'webverse-sign-in', 'popup,width=480,height=640') ?? null);
    if (!opened) {
      waiting = null;
      throw new PublishError('The browser blocked the sign-in window: allow pop-ups for this page and try again.');
    }
    // A window closed without handing anything back ends the wait: the world
    // is still in this tab, and Publish can be pressed again. The return page
    // closes itself right after its message, so the window must be seen
    // closed twice running before the wait is given up.
    let seenClosed = false;
    const stop = every(() => {
      if (!opened.closed) return;
      if (seenClosed && waiting === mine) {
        waiting = null;
        closed(new PublishError('The sign-in window was closed before you were signed in. Your world is still here: publish again to carry on.'));
      }
      seenClosed = true;
    }, 500);
    let back: SignInReturn;
    try {
      back = await message;
    } finally {
      stop();
    }
    const out = await finishSignIn({ origin: new URL(returnPage).origin, message: back, pending: s, fetchImpl: o.fetchImpl });
    if (!out.ok) {
      throw new PublishError(out.reason === 'access_denied' ? 'Sign-in cancelled; nothing was published.' : 'Sign-in did not finish; try again.');
    }
    const token = held(f);
    if (!token) throw new PublishError('Sign-in did not finish; try again.');
    return token;
  };

  return {
    target: async () => (await find())?.target ?? null,
    signedIn: async () => {
      const f = await find();
      return !!f && held(f) !== null;
    },
    async publish(files, worldId) {
      const f = await find();
      if (!f) throw new PublishError('This WebVerse publishes nowhere: its deployment names no publish host, or no sign-in.');
      const token = held(f) ?? (await signIn(f));
      try {
        return await publishFiles({ files, endpoint: f.target.endpoint, token, worldId, fetchImpl: o.fetchImpl as typeof fetch });
      } catch (err) {
        // The protocol's words are the command line's; a 401 here means the
        // host does not take the shell's client, which is the deployment's
        // to fix, not the visitor's.
        if (err instanceof PublishError && err.status === 401) {
          throw new PublishError(`${f.target.host} does not take your sign-in for publishing; nothing was published.`, { cause: err });
        }
        throw err;
      }
    },
    returned(origin, data) {
      const d = data as Partial<SignInReturn> & { type?: unknown };
      if (!waiting || origin !== waiting.origin || !d || d.type !== 'sign-in:return') return;
      const message: SignInReturn = {
        code: typeof d.code === 'string' ? d.code : null,
        state: typeof d.state === 'string' ? d.state : null,
        error: typeof d.error === 'string' ? d.error : null,
      };
      // A return with another state is not this sign-in's; the right one may still come.
      const s = session();
      let expected: unknown;
      try {
        expected = (JSON.parse(s?.getItem(PENDING_SIGN_IN) ?? '{}') as { state?: unknown }).state;
      } catch {
        expected = undefined;
      }
      if (typeof expected === 'string' && message.state !== expected) return;
      const w = waiting;
      waiting = null;
      w.settle(message);
    },
  };
}
