/**
 * Import mode: a model file becomes a world, here, in the tab.
 *
 * A world at an address opens under the two-second rule. A model file the
 * shell is handed instead enters this stage: it says it is converting, runs
 * the converter the command line runs, shows what it understood, opens the
 * world from memory, and offers the folder to keep. Only the importer pays
 * the conversion; whoever opens the saved world gets the fast path.
 *
 * This module is a chunk loaded when a file arrives, never on the first
 * paint: the converter and its readers are heavy and most visits never
 * import anything. A `.blend` goes one chunk further (`blendImport.ts`):
 * Blender itself converts it, and comes back here to open the result.
 */
import { buildWorld, type BuiltWorld } from '@fivesqd/ingest/browser';
import converterWasmUrl from 'assimpjs/dist/assimpjs.wasm?url';
import { classifyImport, type ImportFile } from './importFiles';
import { summarizeImport } from './importSummary';
import { ensureImportServer, ImportServerUnavailable } from './importServer';
import { stageWorldFiles, type StagedWorld } from './worldInMemory';
import { canPickFolder, saveFolder } from './saveWorld';
import { createTabPublisher, type PublishTarget, type TabPublisher } from './publishFromTab';
import { roomForNewWorld, type WorldRoom } from './worldRoom';
import { shellBaseFrom } from '../scene/planet/signIn';
import type { VemlParseResult } from '../veml/parser';

export interface ImportDeps {
  /** Loads a world by address, the way any world is loaded. */
  loadWorld(url: string): Promise<VemlParseResult>;
  /** Leaves the current world and clears its address, so the imported one is not mistaken for it. */
  clearWorld(): void;
  /**
   * Takes the built world in place of this page's own card. A page that
   * only converts and shows, and leaves saving and publishing to the page
   * around it, passes this: it is called once, with the world's files and
   * whether the world opened here, and no save or publish is offered here.
   */
  handBack?(world: { title: string; files: ReadonlyArray<{ path: string; bytes: Uint8Array }> }, shown: boolean): void;
}

export type StageState = 'converting' | 'failed' | 'converted' | 'opened' | 'closed';
export interface StageAction {
  label: string;
  run: () => void;
  disabled?: boolean;
}

// With the sticks shown, the card sits at the top under the menu button, ending above the highest touch button.
const CSS = `[data-webverse-import]{position:fixed;z-index:29;left:12px;bottom:12px;width:min(360px,calc(100vw - 24px));box-sizing:border-box;padding:14px 16px;border-radius:10px;background:rgba(20,20,24,.92);color:#fff;font:14px/1.4 system-ui,sans-serif;box-shadow:0 8px 30px rgba(0,0,0,.5)}[data-webverse-import] h3{margin:0 0 6px;font-size:15px;font-weight:600}[data-webverse-import] p{margin:4px 0;opacity:.9}[data-webverse-import] ul{margin:6px 0;padding-left:18px}[data-webverse-import] li{margin:2px 0;overflow-wrap:anywhere}[data-webverse-import-actions]{display:flex;gap:8px;margin-top:10px}[data-webverse-import] button{flex:1;padding:7px 9px;font:inherit;color:#fff;cursor:pointer;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.35);border-radius:6px}[data-webverse-import] button[disabled]{opacity:.5;cursor:default}[data-webverse-import-note]{font-size:12px;opacity:.7;margin-top:8px}[data-webverse-touch] [data-webverse-import]{top:64px;bottom:auto;max-height:calc(100vh - 400px);overflow-y:auto}`;

let current: StagedWorld | undefined;
let card: HTMLElement | undefined;

function ensureStyle(doc: Document): void {
  if (doc.querySelector('style[data-webverse-import-style]')) return;
  const style = doc.createElement('style');
  style.setAttribute('data-webverse-import-style', '');
  style.textContent = CSS;
  doc.head.appendChild(style);
}

/** The stage's card: one at a time, replaced whole; `closed` takes it away. */
export function showStage(doc: Document, state: StageState, title = '', lines: string[] = [], actions: StageAction[] = [], note?: string): void {
  card?.remove();
  card = undefined;
  if (state === 'closed') return;
  ensureStyle(doc);
  const el = doc.createElement('div');
  el.setAttribute('data-webverse-import', '');
  el.setAttribute('data-state', state);
  el.setAttribute('role', 'status');
  const h = doc.createElement('h3');
  h.textContent = title;
  el.appendChild(h);
  const ul = doc.createElement('ul');
  ul.setAttribute('data-webverse-import-summary', '');
  for (const line of lines) {
    const li = doc.createElement('li');
    li.textContent = line;
    ul.appendChild(li);
  }
  el.appendChild(ul);
  if (actions.length > 0) {
    const row = doc.createElement('div');
    row.setAttribute('data-webverse-import-actions', '');
    for (const a of actions) {
      const b = doc.createElement('button');
      b.type = 'button';
      b.textContent = a.label;
      if (a.disabled) b.disabled = true;
      b.addEventListener('click', a.run);
      row.appendChild(b);
    }
    el.appendChild(row);
  }
  if (note) {
    const p = doc.createElement('p');
    p.setAttribute('data-webverse-import-note', '');
    p.textContent = note;
    el.appendChild(p);
  }
  doc.body.appendChild(el);
  card = el;
}

const closeCard = (doc: Document): StageAction => ({ label: 'Close', run: () => showStage(doc, 'closed') });

const stem = (name: string): string => {
  const dot = name.lastIndexOf('.');
  return dot > 0 ? name.slice(0, dot) : name;
};

/** Writes the folder through the directory picker, or downloads it as a zip where there is none. */
async function saveWorld(doc: Document, built: BuiltWorld): Promise<string> {
  return (await saveFolder(doc, built)) === 'folder'
    ? `Saved ${built.files.length} files. Put the folder on any web host and share the address of its index.veml.`
    : 'Downloaded as a zip. Unzip it onto any web host and share the address of its index.veml.';
}

/** A world folder to save: its title and how to get each file's bytes, in hand or back from the store. */
interface SaveableWorld {
  title: string;
  files: ReadonlyArray<{ path: string; bytes?: Uint8Array; url?: string }>;
  bytesOf?: (url: string) => Promise<Uint8Array | null>;
}

async function materialize(world: SaveableWorld): Promise<BuiltWorld> {
  const files = await Promise.all(
    world.files.map(async (f) => {
      const bytes = f.bytes ?? (f.url && world.bytesOf ? await world.bytesOf(f.url) : null);
      if (!bytes) throw new Error(`${f.path} is no longer in this tab; convert the model again.`);
      return { path: f.path, bytes };
    }),
  );
  return { title: world.title, files } as BuiltWorld;
}

function saveAction(doc: Document, world: SaveableWorld, after: (note?: string) => void): StageAction {
  const picker = canPickFolder(doc);
  return {
    label: picker ? 'Save as VEML…' : 'Download as zip',
    run: () => {
      materialize(world)
        .then((built) => saveWorld(doc, built))
        .then(after, (err: unknown) => {
          if (err instanceof Error && err.name === 'AbortError') return;
          after(`Saving failed: ${err instanceof Error ? err.message : String(err)}`);
        });
    },
  };
}

let publisher: TabPublisher | undefined;

/** The tab's publisher, made once: the shell's deployment says where, and the page's `message` events bring the sign-in back. */
function publisherOf(doc: Document): TabPublisher {
  if (!publisher) {
    const win = doc.defaultView;
    let pending: Storage | undefined;
    try {
      pending = win?.sessionStorage ?? undefined;
    } catch {
      pending = undefined;
    }
    const made = createTabPublisher({
      shellBase: shellBaseFrom(import.meta.url, import.meta.env.DEV),
      fetchImpl: (u, i) => globalThis.fetch(u, i),
      ...(pending ? { pending } : {}),
      openWindow: (url) => win?.open(url, 'webverse-sign-in', 'popup,width=480,height=640') ?? null,
    });
    win?.addEventListener('message', (e: MessageEvent) => made.returned(e.origin, e.data));
    publisher = made;
  }
  return publisher;
}

/** The room a world made now is, where this shell's deployment names a meeting place; empty otherwise. */
export function newWorldRoom(): Promise<WorldRoom | Record<string, never>> {
  return roomForNewWorld(shellBaseFrom(import.meta.url, import.meta.env.DEV), (u, i) => globalThis.fetch(u, i));
}

/** Where this shell publishes, or null; never throws, since the card must show either way. */
async function publishTarget(doc: Document): Promise<PublishTarget | null> {
  try {
    return await publisherOf(doc).target();
  } catch {
    return null;
  }
}

/**
 * Publishes the world in the tab to the shell's host: a new world the first
 * time, the same one again after. The card says where it went, and keeps
 * saying it, since the address is what the person came for.
 */
function publishAction(doc: Document, world: SaveableWorld, target: PublishTarget, published: { worldId?: string; url?: string }, after: (note?: string) => void): StageAction {
  return {
    label: published.worldId ? `Publish again to ${target.host}` : `Publish to ${target.host}`,
    run: () => {
      after(`Publishing to ${target.host}…`);
      materialize(world)
        .then((built) => publisherOf(doc).publish(built.files, published.worldId))
        .then(
          (out) => {
            published.worldId = out.worldId;
            published.url = out.url;
            after(`Published at ${out.url}`);
          },
          (err: unknown) => after(`Publishing failed: ${err instanceof Error ? err.message : String(err)}`),
        );
    },
  };
}

/** The card's actions for a world in hand: the save, the publish where the shell has a host, and the close. */
function worldActions(doc: Document, world: SaveableWorld, target: PublishTarget | null, published: { worldId?: string; url?: string }, again: (note?: string) => void): StageAction[] {
  return [saveAction(doc, world, again), ...(target ? [publishAction(doc, world, target, published, again)] : []), closeCard(doc)];
}

/** Stages a built world through the import server, clearing whatever an earlier import left: one imported world at a time, and the store outlives the page. */
export async function stageBuilt(doc: Document, built: BuiltWorld): Promise<{ staged: StagedWorld; files: Array<{ path: string; url: string }> }> {
  const server = await ensureImportServer(doc.defaultView!);
  await (server.store.clear ? server.store.clear() : current?.release());
  const staged = await stageWorldFiles(built.files, server.store, server.scopeUrl);
  current = staged;
  return { staged, files: built.files.map((f, i) => ({ path: f.path, url: staged.urls[i]! })) };
}

/** What the card shows for a staged world, and where its files are. */
export interface StagedPresentation {
  documentUrl: string;
  title: string;
  modelName: string;
  lines: string[];
  files: Array<{ path: string; url: string; bytes?: Uint8Array }>;
  /** Reads a staged file back when its bytes are not in hand (a world converted on another page of this tab). */
  bytesOf?: (url: string) => Promise<Uint8Array | null>;
}

/** Loads a staged world as any world and shows the card with what was understood and the save. */
export async function presentStaged(doc: Document, p: StagedPresentation, deps: ImportDeps): Promise<void> {
  deps.clearWorld();
  const result = await deps.loadWorld(p.documentUrl);
  if (!result.ok) {
    showStage(doc, 'failed', `Could not open ${p.modelName}`, result.report.errors.map((e) => e.message), [closeCard(doc)]);
    return;
  }
  const world: SaveableWorld = { title: p.title, files: p.files, bytesOf: p.bytesOf };
  const target = await publishTarget(doc);
  const published: { worldId?: string; url?: string } = {};
  const opened = (note?: string): void =>
    showStage(
      doc,
      'opened',
      p.title,
      published.url ? [...p.lines, `Published at ${published.url}`] : p.lines,
      worldActions(doc, world, target, published, opened),
      note ?? (target ? `This world lives in this tab until you save it, or publish it to ${target.host}.` : 'This world lives in this tab until you save it.'),
    );
  opened();
}

/**
 * A built world, opened and offered: staged through the import server, loaded
 * as any world, then the card with what was understood and the save. Where
 * there is no import server the conversion still stands and the folder can
 * still be saved. Shared by every kind of import.
 */
export async function presentBuilt(doc: Document, built: BuiltWorld, modelName: string, deps: ImportDeps): Promise<void> {
  if (deps.handBack) {
    // Shown here, kept there: the page around this one has the save and the publish, and gets the world
    // whether or not this page could open it.
    let shown = false;
    try {
      const { staged: world } = await stageBuilt(doc, built);
      deps.clearWorld();
      shown = (await deps.loadWorld(world.documentUrl)).ok;
    } catch {
      shown = false;
    }
    showStage(doc, 'closed');
    deps.handBack({ title: built.title, files: built.files }, shown);
    return;
  }
  const lines = summarizeImport(built);
  let staged: { staged: StagedWorld; files: Array<{ path: string; url: string }> };
  try {
    staged = await stageBuilt(doc, built);
  } catch (err) {
    const world: SaveableWorld = { title: built.title, files: built.files };
    const target = await publishTarget(doc);
    const published: { worldId?: string; url?: string } = {};
    const converted = (note?: string): void =>
      showStage(
        doc,
        'converted',
        built.title,
        published.url ? [...lines, `Published at ${published.url}`] : lines,
        worldActions(doc, world, target, published, converted),
        note ?? (err instanceof ImportServerUnavailable ? err.message : `Could not open the world here: ${err instanceof Error ? err.message : String(err)}`),
      );
    converted();
    return;
  }
  await presentStaged(
    doc,
    {
      documentUrl: staged.staged.documentUrl,
      title: built.title,
      modelName,
      lines,
      files: staged.files.map((f, i) => ({ ...f, bytes: built.files[i]!.bytes })),
    },
    deps,
  );
}

/**
 * Run one import: classify, convert, open, offer to save. Failures end in the
 * card, never in a rejection: the stage is the surface for them.
 */
export async function runImport(doc: Document, files: readonly ImportFile[], deps: ImportDeps): Promise<void> {
  const classified = classifyImport(files);
  if (classified.kind === 'refused') {
    showStage(doc, 'failed', 'Cannot open this', [classified.reason], [closeCard(doc)]);
    return;
  }
  const { model, sidecars } = classified;
  if (classified.kind === 'blend') {
    const { importBlend } = await import('./blendImport');
    return importBlend(doc, model, sidecars, deps);
  }
  const title = stem(model.name);
  showStage(doc, 'converting', `Opening ${model.name}`, ['Converting the model into a world. This runs here, in your browser; nothing is uploaded.']);
  let built: BuiltWorld;
  try {
    built = await buildWorld(
      { name: model.name, bytes: model.bytes, files: sidecars },
      // The build serves the converter's WebAssembly file at an address of
      // its own; the converter would otherwise look beside its moved module.
      { toolVersion: 'webverse', title, forceMaterialDefaults: true, locateConverterWasm: () => converterWasmUrl, ...(await newWorldRoom()) },
    );
  } catch (err) {
    showStage(doc, 'failed', `Could not open ${model.name}`, [err instanceof Error ? err.message : String(err)], [closeCard(doc)]);
    return;
  }
  await presentBuilt(doc, built, model.name, deps);
}
